import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d as p,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"开放经济会计与经常账户","description":"","frontmatter":{"title":"开放经济会计与经常账户","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/open-ca.md","filePath":"econ/open-ca.md","lastUpdated":1789023840000}'),c={name:"econ/open-ca.md"};function h(C,a,_,E,m,u){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="开放经济会计与经常账户" tabindex="-1">开放经济会计与经常账户 <a class="header-anchor" href="#开放经济会计与经常账户" aria-label="Permalink to &quot;开放经济会计与经常账户&quot;">​</a></h1><div class="epigraph"><p>经常账户不是「竞争力评分」，而是国民储蓄减去国内投资：吸收与产出的差，对应对外净要求权的积累。</p><footer>—— 据 SNA 国外账户；对照 Mundell 把外部平衡写成宏观约束之前的会计身份</footer></div><p><a href="/econ/automatic-stabilizers">上一课</a>（自动稳定器）。在封闭或未写国境的装置里谈乘数。支出恒等里一直有 \\(NX\\)，<a href="/econ/saving-investment-id">储蓄–投资</a>用它当代理。本课的缺口是把对外账户写全：经常账户 \\(CA\\)、资本与金融账户、储备，以及 GDP 与 GNI 的差。购买力平价从下一课起给相对价格；本课先保证符号是账，不是蒙代尔图上的斜率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>封闭时 \\(S=I\\)。开放时国民储蓄可以离开本国资本形成，变成对国外的净债权。缺口是</p> \\[CA \\equiv S-I, \\]<p>在 SNA 口径下与货物服务净出口、要素净收入、经常转移一致（细节科目以手册为准）。\\(CA\\gt 0\\) 是本国吸收 \\(C+I+G\\) 小于国民收入，不是道德上的「盈余美德」。财政课的孪生赤字是这句恒等的部门展开：公共 \\(S^g\\) 下降，若私人 \\(S^p-I\\) 不变，则 \\(CA\\) 下降。</p><p>GDP 课留下的国内与国民之差，在此落地：GNI $= $ GDP \\(+\\) 跨境要素净收入。\\(CA\\) 用国民口径更干净。本课不把 \\(CA\\) 写成汇率的函数——那是 PPP 与蒙代尔。</p><p><span class="marginnote">金融账户记录谁向谁买了哪些资产。经常账户与金融账户（加储备与净误差）对平。恒等不告诉你资本流入是「推动」还是「拉动」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>支出：\\(Y=C+I+G+NX_{\\mathrm{goods,services}}\\)。国民收入再调要素与转移。跨期：一国的 \\(CA\\) 是对未来净出口的要求权变化，欧拉在开放下变成对外净资产的平滑——Obstfeld 一类跨期方法，本课只借用：赤字可以是最优的投资高峰或平滑消费，不必是失衡的同义词。</p>',11)),(e(),s(d,null,{default:o(()=>[A(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%9B%BD%E6%B0%91%E5%82%A8%E8%93%84%20S%22%5D%20--%3E%20CA%5B%22CA%20%3D%20S%E2%88%92I%22%5D%0A%20%20I%5B%22%E5%9B%BD%E5%86%85%E6%8A%95%E8%B5%84%20I%22%5D%20--%3E%20CA%0A%20%20CA%20--%3E%20NFA%5B%22%E5%AF%B9%E5%A4%96%E5%87%80%E8%B5%84%E4%BA%A7%E5%8F%98%E5%8C%96%22%5D%0A%20%20NX%5B%22%E5%87%80%E5%87%BA%E5%8F%A3%E4%B8%8E%E8%A6%81%E7%B4%A0%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20CA%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>储备与汇率制度：央行买外汇，金融账户与储备同时动，经常账户仍由 \\(S-I\\) 决定。不可能三角会把「资本自由流动」写成这一金融账户的开放度；本课只记下账户存在。</p><h3 id="乘数的开放漏出" tabindex="-1">乘数的开放漏出 <a class="header-anchor" href="#乘数的开放漏出" aria-label="Permalink to &quot;乘数的开放漏出&quot;">​</a></h3><p>\\(G\\) 上升提高吸收，一部分变成进口，\\(CA\\) 变差，封闭乘数缩小。李嘉图与欧拉仍适用：若减税被对外借贷平滑，对外净资产下降，未来要用净出口偿还。批判仍在：开放度与汇率规则都进简化式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每一笔未用于国内 \\(C+I+G\\) 的国民产出，变成对国外的净要求权；反过来，吸收超过产出就消耗对外资产或增加对外负债。汇率、利率、相对价格决定的是<strong>均衡中</strong> \\(S\\)、\\(I\\) 如何调整，不是恒等是否成立。货币中性的长期：名义汇率可以变，\\(CA\\) 的实物路径由跨期偏好、投资机会与净国外资产决定。</p><p>财政扩张在浮动与固定下对 \\(CA\\) 的短期效应不同，那是蒙代尔–弗莱明。会计先行：无论哪一种，\\(S-I\\) 必须等于 \\(CA\\)。</p><p>吸收法：\\(CA=Y-A\\)，\\(A=C+I+G\\)。贬值要改善 \\(CA\\)，必须 \\(Y\\) 升或 \\(A\\) 降。这是会计加一句行为空位。GDP 与 GNI 的差在跨境要素落地。孪生赤字是恒等的部门展开，不是因果。</p><p><span class="marginnote">BPM 把直接投资、组合、其他、储备写在金融账户。本课用「资本流动」作口语，与科目名不完全同义。恒等不告诉你流入是推动还是拉动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把双边贸易差额当成福利。不要把统计误差当理论。量化栏的外汇微观结构、CIP 偏差，不是 SNA 科目；本栏加总到宏观净额为止。公司如何在境外融资，留给资本结构课。发展中经济的 \\(CA\\) 逆差可以是 \\(I\\) 高，不是 \\(S\\) 不道德。</p><p>后课默认：写下开放宏观时，\\(CA=S-I\\) 是恒等，事前均衡另说。下一课用一价定律与购买力平价给相对价格与汇率一个长期锚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(CA=S-I\\) 是国外账户恒等，不是竞争力排名。</li><li>GDP 与 GNI 差在跨境要素；经常账户含净出口、要素、转移。</li><li>跨期上赤字可以是平滑或投资，不必等于「失衡」。</li><li>吸收法把 \\(CA\\) 写成产出减吸收，行为仍空着。</li><li>汇率制度改变的是调整渠道，不是恒等。</li><li>出处：SNA 国外账户；IMF BPM。</li></ul>',13))])}const B=i(c,[["render",h]]);export{I as __pageData,B as default};
